    excerpt: "\u062D\u062A\u06CC \u0627\u06AF\u0631 \u067E\u0646\u062C\u0631\u0647 \u062C\u0646\u0648\u0628\u06CC \u0628\u0627 \u0646\u0648\u0631 \u0633\u0631\u0634\u0627\u0631 \u0646\u062F\u0627\u0631\u06CC\u062F\u060C \u0627\u06CC\u0646 \u06F4 \u06AF\u06CC\u0627\u0647 \u062A\u0635\u0641\u06CC\u0647\u200C\u06A9\u0646\u0646\u062F\u0647 \u0647\u0648\u0627 \u062F\u0631 \u062A\u0627\u0631\u06CC\u06A9\u200C\u062A\u0631\u06CC\u0646 \u06AF\u0648\u0634\u0647\u200C\u0647\u0627\u06CC \u062E\u0627\u0646\u0647 \u0647\u0645 \u0628\u0627 \u0633\u0631\u0633\u0628\u0632\u06CC \u0631\u0634\u062F \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F.",
